import os

def read_file(filename):
    base = os.path.realpath("/var/www/files")
    path = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath([base, path]) != base:
        raise ValueError("chemin invalide")
    with open(path, "r") as f:
        return f.read()

