from urllib.parse import urlparse
from flask import redirect

def login_done(next):
    parsed = urlparse(next)
    if parsed.scheme or parsed.netloc or not parsed.path.startswith("/") or parsed.path.startswith("//") or "\\" in next:
        next = "/"
    return redirect(next)

